/** Markdown building blocks the census docs share. */
import { existsSync, readFileSync, writeFileSync } from "node:fs";

export const GENERATED_HEADER = [
  "<!-- Generated by scripts/reports/census/index.mjs. Do not edit by hand. -->",
  "",
  "Run `pnpm census` after changing a tool, skill, prompt, command, persona or env var.",
  "",
].join("\n");

export const bullets = (items) => items.map((item) => "- `" + item + "`").join("\n");

export function table(headers, rows) {
  const widths = headers.map((h, i) => Math.max(String(h).length, ...rows.map((row) => String(row[i] ?? "").length)));
  const rule = (row) => row.map((cell, i) => String(cell ?? "").padEnd(widths[i])).join(" | ");
  return ["| " + rule(headers) + " |", "| " + widths.map((w) => "-".repeat(w)).join(" | ") + " |", ...rows.map((row) => "| " + rule(row) + " |")].join("\n");
}

/** Refresh the block between the markers of one document. */
export function upsertBlock(filePath, marker, content) {
  const text = existsSync(filePath) ? readFileSync(filePath, "utf8") : "";
  const begin = "<!-- census:begin:" + marker + " -->";
  const end = "<!-- census:end:" + marker + " -->";
  const block = begin + "\n" + content + "\n" + end;
  const beginIndex = text.indexOf(begin);
  const endIndex = text.indexOf(end);
  const next =
    beginIndex !== -1 && endIndex > beginIndex ? text.slice(0, beginIndex) + block + text.slice(endIndex + end.length) : text.replace(/\s*$/, "") + "\n\n" + block + "\n";
  writeFileSync(filePath, next.trimEnd() + "\n\n");
}
